void solve() {
    int n, q; cin >> n >> q;
    vector<int> maxR(n+1, -1);
    for (int i = 1; i <= q; i++) {
        int u, v; cin >> u >> v;
        maxR[u] = max(maxR[u], v);
    }
    vector<pair<int, int>> ranges;
    int mr = 0;
    for (int i = 1; i <= n; i++) {
        if (maxR[i] > mr) {
            mr = maxR[i];
            ranges.push_back({i, maxR[i]});
        }
    }
    q = ranges.size();
    int lo = 0, hi = q-1;
    int ans = 0;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        int l = ranges[mid].first;
        int r = ranges[mid].second;
        int pref = ask(1, r);
        int suff = ask(l, n);
        ans = max(ans, min(pref, suff));
        if (pref > suff) {
            hi = mid-1;
        }
        else lo = mid+1;
    }
    cout << "! " << ans << endl;
}

